<?php declare(strict_types=1); /** @var Closure(mixed): string $escape */ $allUnits=$unit['id']===null; ?>
<div class="actions"><div><span class="status">CRM · <?= $escape($unit['name']) ?></span><h1>Contatos</h1></div><?php if(!$allUnits):?><a href="<?= $escape($basePath) ?>/crm/contacts/create">Novo contato</a><?php endif;?></div>
<?php if($allUnits):?><p class="meta">Visão consolidada das unidades autorizadas. Selecione uma unidade específica para cadastrar ou editar.</p><?php endif;?>
<?php if($message):?><p class="alert alert-success"><?= $escape($message) ?></p><?php endif;?><?php if($error):?><p class="alert alert-danger"><?= $escape($error) ?></p><?php endif;?>
<form method="get" action="<?= $escape($basePath) ?>/crm/contacts" class="d-flex gap-2 align-items-center"><label class="visually-hidden" for="q">Buscar</label><input id="q" name="q" value="<?= $escape($search) ?>" placeholder="Nome, telefone, e-mail ou curso"><button type="submit">Buscar</button></form>
<table><thead><tr><th>Contato</th><?php if($allUnits):?><th>Unidade</th><?php endif;?><th>Status</th><th>Curso</th><th>Interesse</th><th>Polo</th><th>Entrada</th><th></th></tr></thead><tbody>
<?php if($contacts===[]):?><tr><td colspan="8">Nenhum contato encontrado.</td></tr><?php endif;?>
<?php foreach($contacts as $item):?><tr><td><strong><?= $escape($item['name']) ?></strong><br><span class="meta"><?= $escape($item['phone'] ?: $item['email'] ?: 'Sem contato informado') ?></span></td><?php if($allUnits):?><td><?= $escape($item['unit_name']) ?></td><?php endif;?><td><span style="color:<?= $escape($item['status_color']) ?>;font-weight:700"><?= $escape($item['status_name']) ?></span></td><td><?= $escape($item['course'] ?: '—') ?></td><td><?= $item['interest_score']===null?'—':$escape($item['interest_score'].'/10') ?></td><td><?= $escape($item['origin_city'] ?: '—') ?></td><td><?= $escape(date('d/m/Y H:i',strtotime((string)$item['registered_at']))) ?></td><td><?php if(!$allUnits):?><a href="<?= $escape($basePath) ?>/crm/contacts/<?= $escape($item['id']) ?>/edit">Editar</a><?php endif;?></td></tr><?php endforeach;?></tbody></table>
